1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} (so the request telephone
11	 * is E.164 and the email lower-cased) and before {@link BuildOwner}. Rejects the request with
12	 * {@link DuplicateIdentityException} (handled as 409) when it collides with an existing owner.
13	 *
14	 * <p>Duplicate detection is expressed through the single {@code identityKey} = normalized telephone,
15	 * email and {@link OwnerIdentity#householdId householdId} (derived from lastName + postcode). The
16	 * request collides only when its <em>whole</em> identityKey equals an existing owner's: same telephone,
17	 * same email <em>and</em> same household. A differing component — a distinct telephone, email, or
18	 * household — is a separate identity that is allowed, so several owners can share a household as long as
19	 * their contact details differ (each is then a household member whose membership level is capped by
20	 * {@link CapMembershipLevel}). {@code sharesHousehold: true} still bypasses the check entirely.
21	 */
22	public class EnsureUniqueOwnerIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        // A declared household member opts in with sharesHousehold=true and bypasses the whole
27	        // duplicate block, so it is created even though it shares an existing owner's household.
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
32	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
33	        for (Owner existing : ownerRepository.findAll()) {
34	            // A soft-deleted owner is no longer a live identity: skip it, so a duplicate that would
35	            // otherwise block is allowed when its only match has been deleted.
36	            if (Boolean.TRUE.equals(existing.getDeleted())) {
37	                continue;
38	            }
39	            // Duplicate only when the whole identityKey matches: same telephone, email AND household.
40	            String existingHousehold =
41	                    OwnerIdentity.householdId(existing.getLastName(), existing.getPostcode());
42	            String existingKey = OwnerIdentity.key(OwnerIdentity.toE164(existing.getTelephone()),
43	                    OwnerIdentity.normalizeEmail(existing.getEmail()), existingHousehold);
44	            if (identityKey.equals(existingKey)) {
45	                throw new DuplicateIdentityException(identityKey);
46	            }
47	        }
48	    }
49	}
