1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Runs after the owner is built but before it is saved. By this point the request has already passed
10	 * {@link EnsureUniqueOwnerIdentity}, so it is <em>not</em> a hard duplicate. This step records a
11	 * <em>soft</em> match: when the new owner shares an existing owner's {@code lastName} (case-insensitive)
12	 * and {@code postcode} but has a different (normalized) telephone, it is still created, with the
13	 * owner's {@code possibleDuplicate} flag set to true and {@code possibleDuplicateOf} set to the matching
14	 * owner's id. Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is null. Both
15	 * values are mutated in place via {@code @Val} for the save/respond steps to persist and return.
16	 *
17	 * <p>A declared household member (the request opted in with {@code sharesHousehold: true}) is
18	 * <em>never</em> flagged: it shares an existing owner's household by design, so it is not a suspected
19	 * duplicate.
20	 *
21	 * <p>When more than one existing owner soft-matches, the lowest id is recorded.
22	 */
23	public class FlagPossibleDuplicate {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            owner.setPossibleDuplicate(false);
28	            owner.setPossibleDuplicateOf(null);
29	            return;
30	        }
31	        String lastName = owner.getLastName();
32	        String postcode = owner.getPostcode();
33	        String telephone = owner.getTelephone();
34	        Integer matchId = null;
35	        if (postcode != null && !postcode.isBlank()) {
36	            for (Owner existing : ownerRepository.findAll()) {
37	                if (Boolean.TRUE.equals(existing.getDeleted())) {
38	                    continue;
39	                }
40	                if (equalsIgnoreCase(lastName, existing.getLastName())
41	                        && postcode.equals(existing.getPostcode())
42	                        && !equalsNullSafe(telephone, existing.getTelephone())
43	                        && existing.getId() != null
44	                        && (matchId == null || existing.getId() < matchId)) {
45	                    matchId = existing.getId();
46	                }
47	            }
48	        }
49	        owner.setPossibleDuplicate(matchId != null);
50	        owner.setPossibleDuplicateOf(matchId);
51	    }
52	
53	    private static boolean equalsIgnoreCase(String a, String b) {
54	        return a == null ? b == null : a.equalsIgnoreCase(b);
55	    }
56	
57	    private static boolean equalsNullSafe(String a, String b) {
58	        return a == null ? b == null : a.equals(b);
59	    }
60	}
