1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
10	
11	/**
12	 * Normalizes the optional owner email. Email may be absent: a null or blank value is left untouched
13	 * and passes through. When present it is trimmed and lower-cased, then required to be a syntactically
14	 * valid address; the normalized (lower-cased) value is written back onto the validated body (mutated in
15	 * place via {@code @Val}) so downstream steps store and return it lower-cased. A present-but-invalid
16	 * address is rejected by throwing {@link InvalidEmailException} (handled as 400). An otherwise valid
17	 * address whose domain is on the disposable-domain blocklist is likewise rejected as 400.
18	 */
19	public class NormalizeOwnerEmail {
20	
21	    private static final Pattern EMAIL =
22	            Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
23	
24	    /** Disposable email domains that are not accepted for owner registration. */
25	    private static final Set<String> DISPOSABLE_DOMAINS =
26	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
27	
28	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
29	        String email = request.getEmail();
30	        if (email == null || email.isBlank()) {
31	            return;
32	        }
33	        String normalized = email.trim().toLowerCase(Locale.ROOT);
34	        if (!EMAIL.matcher(normalized).matches()) {
35	            throw new InvalidEmailException(email);
36	        }
37	        String domain = normalized.substring(normalized.indexOf('@') + 1);
38	        if (DISPOSABLE_DOMAINS.contains(domain)) {
39	            throw new InvalidEmailException(email);
40	        }
41	        request.setEmail(normalized);
42	    }
43	}
