1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Runs after required-field validation and before {@link BuildOwner}. Normalizes the telephone into
9	 * E.164 form: spaces, dashes and brackets are stripped; a leading {@code '+'} and its country code are
10	 * kept when present, otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
11	 * dropped from the national digits. The result must carry 8 to 15 digits after the {@code '+'}. So
12	 * {@code '0412 345 678'} becomes {@code '+61412345678'}. The E.164 value is written back onto the
13	 * validated body (mutated in place via {@code @Val}) so downstream steps store and return it. A
14	 * telephone that cannot form valid E.164 is rejected by throwing {@link InvalidTelephoneException}
15	 * (handled as 400).
16	 */
17	public class NormalizeOwnerTelephone {
18	
19	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
20	        request.setTelephone(TelephoneE164.toE164(request.getTelephone()));
21	    }
22	}
