1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs after {@link AssignOwnerHousehold} (which sets the deterministic {@code householdId}) and before
9	 * the owner is saved. Sets the owner's {@code householdSize} to the number of members its household has
10	 * after this create: the existing owners already sharing the same {@code householdId} plus this new one
11	 * (not yet persisted). The household is keyed on (lastName, postcode), so each existing owner's household
12	 * is derived the same deterministic way rather than read from a stored value. The size is mutated in
13	 * place via {@code @Val} so the save/respond steps persist and return it.
14	 */
15	public class CountHouseholdMembers {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String householdId = owner.getHouseholdId();
19	        int size = 1; // this owner, not yet persisted
20	        if (householdId != null) {
21	            size += (int) ownerRepository.findAll().stream()
22	                    .filter(existing -> householdId.equals(
23	                            OwnerIdentity.householdId(existing.getLastName(), existing.getPostcode())))
24	                    .count();
25	        }
26	        owner.setHouseholdSize(size);
27	    }
28	}
