1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.OptionalInt;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.util.MembershipLevel;
10	
11	/**
12	 * Runs after {@link CountNamesakes} and {@link CountHouseholdMembers} (so the owner's
13	 * {@code namesakeCount} and {@code householdSize} are set) and before the owner is saved. Derives the
14	 * new owner's membership level and caps it at one above the highest membership level currently held by
15	 * an existing member of the same household — the owners already sharing this owner's deterministic
16	 * {@code householdId} (keyed on lastName + postcode, the same way {@link CountHouseholdMembers} finds
17	 * them). With no existing household member no cap applies. The (possibly capped) level is stored on the
18	 * owner via {@code @Val} so {@code SaveOwner} persists it and the response mapper returns it verbatim.
19	 */
20	public class CapMembershipLevel {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        LocalDate today = LocalDate.now();
24	        int level = levelOf(owner, today);
25	        String householdId = owner.getHouseholdId();
26	        if (householdId != null) {
27	            OptionalInt maxExisting = ownerRepository.findAll().stream()
28	                    .filter(existing -> householdId.equals(
29	                            OwnerIdentity.householdId(existing.getLastName(), existing.getPostcode())))
30	                    .mapToInt(existing -> levelOf(existing, today))
31	                    .max();
32	            if (maxExisting.isPresent()) {
33	                level = Math.min(level, maxExisting.getAsInt() + 1);
34	            }
35	        }
36	        owner.setMembershipLevel(level);
37	    }
38	
39	    /** An owner's membership level: the stored value when already assigned, otherwise derived from its
40	     *  fields the same way the response mapper derives it. */
41	    private static int levelOf(Owner owner, LocalDate today) {
42	        Integer stored = owner.getMembershipLevel();
43	        if (stored != null) {
44	            return stored;
45	        }
46	        return MembershipLevel.level(MembershipLevel.points(owner.getEmail(), owner.getNamesakeCount(),
47	                owner.getHouseholdSize(), owner.getRegistrationDate(), today));
48	    }
49	}
