1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a create-owner request's derived {@code identityKey} (normalized telephone, email and
5	 * household id) exactly matches an existing owner's — i.e. it is a full-key duplicate. Handled by
6	 * {@link DuplicateIdentityExceptionHandler}, which responds 409 (Conflict).
7	 */
8	public class DuplicateIdentityException extends Exception {
9	
10	    private final String identityKey;
11	
12	    public DuplicateIdentityException(String identityKey) {
13	        super("An owner with identity '" + identityKey + "' already exists");
14	        this.identityKey = identityKey;
15	    }
16	
17	    public String getIdentityKey() {
18	        return this.identityKey;
19	    }
20	}
