3	import java.util.Map;
4	
5	import net.officefloor.plugin.section.clazz.Parameter;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.http.HttpStatus;
8	import org.springframework.http.ResponseEntity;
9	
10	public class DuplicateIdentityExceptionHandler {
11	
12	    public void handle(@Parameter DuplicateIdentityException ex,
13	            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
14	        response.send(ResponseEntity.status(HttpStatus.CONFLICT)
15	                .body(Map.of("errors", Map.of("identityKey", ex.getMessage()))));
16	    }
17	}
