package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Derives an owner's {@code identityKey} — the single value all duplicate detection is expressed
 * through. The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or
 * empty)}: a full-key match with an existing owner is a duplicate (409); any differing component (a
 * different telephone, email, or household) is a distinct identity that is allowed.
 *
 * <p>Not an OfficeFloor function class — a plain helper shared by the create-owner steps so the key
 * derived at the uniqueness check, the household id assigned to the entity, and the key returned in
 * the response are all computed the same way.
 */
public final class OwnerIdentity {

    private OwnerIdentity() {
    }

    /**
     * Assembles the identity key from its three components. {@code telephone} is expected in E.164
     * form and {@code email} already normalized (trimmed, lower-cased); a null/blank email or a null
     * householdId contributes an empty component.
     */
    public static String key(String telephone, String email, String householdId) {
        String tel = telephone == null ? "" : telephone;
        String mail = (email == null || email.isBlank()) ? "" : email;
        String hh = householdId == null ? "" : householdId;
        return tel + "|" + mail + "|" + hh;
    }

    /** Best-effort E.164 for a stored telephone; falls back to the raw value when it cannot form E.164. */
    public static String toE164(String telephone) {
        try {
            return TelephoneE164.toE164(telephone);
        }
        catch (InvalidTelephoneException ex) {
            return telephone;
        }
    }

    /** Trimmed, lower-cased email, or null when absent — matching {@link NormalizeOwnerEmail}. */
    public static String normalizeEmail(String email) {
        if (email == null || email.isBlank()) {
            return null;
        }
        return email.trim().toLowerCase(Locale.ROOT);
    }

    /**
     * Stable, shared household id: the first 12 upper-hex chars of SHA-256 over the canonical last
     * name and the postcode ({@code normalizedLastName + '|' + postcode}), so every owner with the
     * same last name and postcode derives the same value automatically — the household is keyed on
     * (lastName, postcode) alone. A null postcode contributes an empty component.
     */
    public static String householdId(String lastName, String postcode) {
        String normalizedLastName = canonicalName(lastName);
        String pc = postcode == null ? "" : postcode;
        try {
            byte[] hash = MessageDigest.getInstance("SHA-256")
                    .digest((normalizedLastName + "|" + pc).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", hash[i]));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** Lower-cased, trimmed, with any run of whitespace collapsed to a single space. */
    private static String canonicalName(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} (so the request telephone
 * is E.164 and the email lower-cased) and before {@link BuildOwner}. Rejects the request with
 * {@link DuplicateIdentityException} (handled as 409) when it collides with an existing owner.
 *
 * <p>Duplicate detection is expressed through the single {@code identityKey} = normalized telephone,
 * email and {@link OwnerIdentity#householdId householdId} (derived from lastName + postcode). The
 * request collides only when its <em>whole</em> identityKey equals an existing owner's: same telephone,
 * same email <em>and</em> same household. A differing component — a distinct telephone, email, or
 * household — is a separate identity that is allowed, so several owners can share a household as long as
 * their contact details differ (each is then a household member whose membership level is capped by
 * {@link CapMembershipLevel}). {@code sharesHousehold: true} still bypasses the check entirely.
 */
public class EnsureUniqueOwnerIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        // A declared household member opts in with sharesHousehold=true and bypasses the whole
        // duplicate block, so it is created even though it shares an existing owner's household.
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
        for (Owner existing : ownerRepository.findAll()) {
            // A soft-deleted owner is no longer a live identity: skip it, so a duplicate that would
            // otherwise block is allowed when its only match has been deleted.
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue;
            }
            // Duplicate only when the whole identityKey matches: same telephone, email AND household.
            String existingHousehold =
                    OwnerIdentity.householdId(existing.getLastName(), existing.getPostcode());
            String existingKey = OwnerIdentity.key(OwnerIdentity.toE164(existing.getTelephone()),
                    OwnerIdentity.normalizeEmail(existing.getEmail()), existingHousehold);
            if (identityKey.equals(existingKey)) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}

